//! Runtime-facing evaluation helpers.\nuse crate::safety::{CrisisModel, SafetyDecision, SafetyShield};\n\n#[derive(Debug, Clone, Copy, Default)]\npub struct SafetyMetrics { pub tp:u32, pub tn:u32, pub fp:u32, pub fn_:u32 }\nimpl SafetyMetrics {\n    pub fn precision(&self)->f32 { if self.tp+self.fp==0 {0.0} else {self.tp as f32/(self.tp+self.fp) as f32} }\n    pub fn recall(&self)->f32 { if self.tp+self.fn_==0 {0.0} else {self.tp as f32/(self.tp+self.fn_) as f32} }\n    pub fn fpr(&self)->f32 { if self.fp+self.tn==0 {0.0} else {self.fp as f32/(self.fp+self.tn) as f32} }\n}\npub fn evaluate_safety<M:CrisisModel>(shield:&SafetyShield<M>, cases:&[(String,bool)]) -> SafetyMetrics {\n    let mut m=SafetyMetrics::default();\n    for (input, expected) in cases {\n        let actual=matches!(shield.pre_filter(input).decision,SafetyDecision::Crisis);\n        match (*expected,actual) {(true,true)=>m.tp+=1,(false,false)=>m.tn+=1,(false,true)=>m.fp+=1,(true,false)=>m.fn_+=1};\n    } m\n}\n